CREATE TABLE IF NOT EXISTS paper_signals(namespace TEXT NOT NULL,id TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,bar_date TEXT NOT NULL,side TEXT NOT NULL CHECK(side IN('BUY','SELL')),status TEXT NOT NULL,reason TEXT NOT NULL,created_at TEXT NOT NULL,eligible_date TEXT NOT NULL,PRIMARY KEY(namespace,id));
CREATE TABLE IF NOT EXISTS paper_positions(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>=0),entry_price REAL NOT NULL CHECK(entry_price>0),entry_at TEXT NOT NULL,high_water REAL NOT NULL CHECK(high_water>0),mark_price REAL,mark_at TEXT,updated_at TEXT NOT NULL,pending_exit INTEGER NOT NULL DEFAULT 0,pending_exit_since TEXT,PRIMARY KEY(namespace,strategy,symbol));
CREATE TABLE IF NOT EXISTS paper_fills(id INTEGER PRIMARY KEY AUTOINCREMENT,namespace TEXT NOT NULL,signal_id TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,side TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),price REAL NOT NULL CHECK(price>0),quote_at TEXT NOT NULL,filled_at TEXT NOT NULL,reason TEXT NOT NULL,realized_pnl REAL NOT NULL,cashflow REAL NOT NULL,execution_path TEXT NOT NULL DEFAULT 'LTP_LEGACY' CHECK(execution_path IN('LTP_LEGACY','FEED_OPEN','AUCTION_CAPTURE','FALLBACK_OPEN')),UNIQUE(namespace,signal_id));
CREATE TABLE IF NOT EXISTS paper_watermarks(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,bar_date TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol));
CREATE TABLE IF NOT EXISTS paper_pnl(namespace TEXT NOT NULL,day TEXT NOT NULL,as_of TEXT NOT NULL,report_json TEXT NOT NULL,PRIMARY KEY(namespace,day));
CREATE TABLE IF NOT EXISTS paper_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,namespace TEXT NOT NULL,kind TEXT NOT NULL,at TEXT NOT NULL,status TEXT NOT NULL,details_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_quote_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,namespace TEXT NOT NULL,symbol TEXT NOT NULL,observed_at TEXT NOT NULL,quote_at TEXT,price REAL,accepted INTEGER NOT NULL,reason TEXT NOT NULL,source TEXT NOT NULL DEFAULT 'FYERS_QUOTES');
CREATE TABLE IF NOT EXISTS paper_data_audit(namespace TEXT NOT NULL,symbol TEXT NOT NULL,bar_date TEXT NOT NULL,reason TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(namespace,symbol,bar_date,reason));
CREATE TABLE IF NOT EXISTS paper_meta(namespace TEXT NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL,PRIMARY KEY(namespace,key));

CREATE INDEX IF NOT EXISTS paper_signals_pending_idx ON paper_signals(namespace,status);
CREATE INDEX IF NOT EXISTS paper_fills_day_idx ON paper_fills(namespace,filled_at);
CREATE INDEX IF NOT EXISTS paper_positions_open_idx ON paper_positions(namespace,qty);
CREATE TABLE IF NOT EXISTS paper_charge_policies(version TEXT PRIMARY KEY,policy_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_fill_costs(namespace TEXT NOT NULL,fill_id INTEGER NOT NULL,day TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,isin TEXT NOT NULL,side TEXT NOT NULL,turnover_paise INTEGER NOT NULL,policy_version TEXT NOT NULL,components_json TEXT NOT NULL,total_paise INTEGER NOT NULL,entry_at TEXT NOT NULL,gross_cashflow_paise INTEGER NOT NULL,net_cashflow_paise INTEGER NOT NULL,PRIMARY KEY(namespace,fill_id));
CREATE TABLE IF NOT EXISTS paper_dp_debits(namespace TEXT NOT NULL,day TEXT NOT NULL,isin TEXT NOT NULL,fill_id INTEGER NOT NULL,amount_paise INTEGER NOT NULL,PRIMARY KEY(namespace,day,isin));
CREATE TABLE IF NOT EXISTS paper_entry_cohorts(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,entry_at TEXT NOT NULL,signal_bar TEXT NOT NULL,strategies_json TEXT NOT NULL,cohort TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol,entry_at));
CREATE TABLE IF NOT EXISTS paper_scan_batches(namespace TEXT NOT NULL,bar_date TEXT NOT NULL,scanned_at TEXT NOT NULL,status TEXT NOT NULL,report_json TEXT NOT NULL,PRIMARY KEY(namespace,bar_date));
CREATE TABLE IF NOT EXISTS paper_qualifier_states(namespace TEXT NOT NULL,bar_date TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,qualified INTEGER NOT NULL,checklist_json TEXT NOT NULL,plan_json TEXT NOT NULL,scanned_at TEXT NOT NULL,PRIMARY KEY(namespace,bar_date,strategy,symbol));
CREATE TABLE IF NOT EXISTS paper_monitor_health(namespace TEXT PRIMARY KEY,pid INTEGER NOT NULL,heartbeat_at TEXT NOT NULL,status TEXT NOT NULL,detail_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_eod(namespace TEXT NOT NULL,day TEXT NOT NULL,as_of TEXT NOT NULL,report_json TEXT NOT NULL,PRIMARY KEY(namespace,day));
CREATE INDEX IF NOT EXISTS paper_cost_day_idx ON paper_fill_costs(namespace,day);
CREATE INDEX IF NOT EXISTS paper_qualified_bar_idx ON paper_qualifier_states(namespace,bar_date,qualified,symbol);

-- Versioned two-layer entry gate (additive, separate from demo tables).
CREATE TABLE IF NOT EXISTS paper_prefilter_policies(version TEXT PRIMARY KEY,policy_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_prefilter_states(namespace TEXT NOT NULL,bar_date TEXT NOT NULL,symbol TEXT NOT NULL,policy_version TEXT NOT NULL,status TEXT NOT NULL,metrics_json TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(namespace,bar_date,symbol,policy_version));
CREATE TABLE IF NOT EXISTS paper_entry_gate_proofs(namespace TEXT NOT NULL,signal_id TEXT NOT NULL,bar_date TEXT NOT NULL,symbol TEXT NOT NULL,policy_version TEXT NOT NULL,PRIMARY KEY(namespace,signal_id));


CREATE TABLE IF NOT EXISTS paper_history_gap_checks(namespace TEXT NOT NULL,symbol TEXT NOT NULL,trade_date TEXT NOT NULL,checked_at TEXT NOT NULL,outcome TEXT NOT NULL,retry_after TEXT NOT NULL,details_json TEXT NOT NULL,PRIMARY KEY(namespace,symbol,trade_date));

-- Additive immutable live-input provenance. Raw OHLCV is never deleted.
CREATE TABLE IF NOT EXISTS paper_input_policies(version TEXT PRIMARY KEY,policy_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_input_evidence(version TEXT PRIMARY KEY,policy_version TEXT NOT NULL,evidence_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_entry_input_proofs(namespace TEXT NOT NULL,signal_id TEXT NOT NULL,policy_version TEXT NOT NULL,bar_date TEXT NOT NULL,observed_at TEXT NOT NULL,PRIMARY KEY(namespace,signal_id));

-- Durable allowlisted paper-event audit and local session guardian.
CREATE TABLE IF NOT EXISTS paper_events(namespace TEXT NOT NULL,event_id TEXT NOT NULL,run_id TEXT NOT NULL,session_day TEXT NOT NULL,source_at TEXT NOT NULL,recorded_at TEXT NOT NULL,event_type TEXT NOT NULL,severity TEXT NOT NULL,outcome TEXT NOT NULL,strategy INTEGER,symbol TEXT,bar_date TEXT,signal_id TEXT,policy_version TEXT,input_policy_version TEXT,data_json TEXT NOT NULL,persisted_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%f+00:00','now')),PRIMARY KEY(namespace,event_id));CREATE INDEX IF NOT EXISTS paper_events_session ON paper_events(namespace,session_day,recorded_at,event_id);CREATE INDEX IF NOT EXISTS paper_events_run ON paper_events(namespace,run_id);
CREATE TABLE IF NOT EXISTS paper_guardian_health(namespace TEXT PRIMARY KEY,pid INTEGER NOT NULL,process_start TEXT NOT NULL,session_day TEXT NOT NULL,heartbeat_at TEXT NOT NULL,status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS paper_decisions(namespace TEXT NOT NULL,seq INTEGER NOT NULL,correlation_id TEXT NOT NULL,decision_type TEXT NOT NULL CHECK(decision_type IN('ENTRY','EXIT','SKIP','HOLD')),strategy INTEGER,symbol TEXT,signal_id TEXT,cause TEXT,rule TEXT,execution_path TEXT,source_at TEXT NOT NULL,recorded_at TEXT NOT NULL,prev_hash TEXT NOT NULL,entry_hash TEXT NOT NULL,payload_json TEXT NOT NULL,PRIMARY KEY(namespace,seq));
CREATE INDEX IF NOT EXISTS paper_decisions_correlation ON paper_decisions(namespace,correlation_id,seq);
CREATE TABLE IF NOT EXISTS paper_shadow_positions(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>=0),entry_price REAL NOT NULL,entry_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol));
CREATE TABLE IF NOT EXISTS paper_shadow_costs(namespace TEXT NOT NULL,signal_id TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,side TEXT NOT NULL,qty INTEGER NOT NULL,price REAL NOT NULL,total_paise INTEGER NOT NULL,net_cashflow_paise INTEGER NOT NULL,filled_at TEXT NOT NULL,PRIMARY KEY(namespace,signal_id));
CREATE TABLE IF NOT EXISTS paper_price_bands(symbol TEXT NOT NULL,trade_date TEXT NOT NULL,upper_price REAL,lower_price REAL,series TEXT,surveillance TEXT,fo_eligible INTEGER NOT NULL DEFAULT 0,source TEXT NOT NULL,PRIMARY KEY(symbol,trade_date));
CREATE TABLE IF NOT EXISTS paper_upper_circuit_blocks(namespace TEXT NOT NULL,signal_id TEXT NOT NULL,trade_date TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,signal_id,trade_date));
CREATE TABLE IF NOT EXISTS paper_circuit_locks(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,trade_date TEXT NOT NULL,direction TEXT NOT NULL,locked_price REAL NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol,trade_date));
CREATE TABLE IF NOT EXISTS paper_corporate_actions(symbol TEXT NOT NULL,ex_date TEXT NOT NULL,kind TEXT NOT NULL,ratio_num INTEGER,ratio_den INTEGER,cash_paise INTEGER,source TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(symbol,ex_date,kind));
CREATE TABLE IF NOT EXISTS paper_state_scales(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,ex_date TEXT NOT NULL,kind TEXT NOT NULL,old_qty INTEGER NOT NULL,new_qty INTEGER NOT NULL,fraction_num INTEGER NOT NULL,fraction_den INTEGER NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol,ex_date,kind));
CREATE TABLE IF NOT EXISTS paper_cash_credits(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,ex_date TEXT NOT NULL,kind TEXT NOT NULL,amount_paise INTEGER NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol,ex_date,kind));
CREATE TABLE IF NOT EXISTS paper_indicator_state(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,upperband REAL,lowerband REAL,prev_close REAL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol));
CREATE TABLE IF NOT EXISTS paper_manual_reviews(namespace TEXT NOT NULL,strategy INTEGER NOT NULL,symbol TEXT NOT NULL,ex_date TEXT NOT NULL,kind TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,strategy,symbol,ex_date,kind));
CREATE TABLE IF NOT EXISTS paper_equity_closes(namespace TEXT NOT NULL,book TEXT NOT NULL,strategy INTEGER NOT NULL,day TEXT NOT NULL,equity_paise INTEGER NOT NULL,PRIMARY KEY(namespace,book,strategy,day));
CREATE TABLE IF NOT EXISTS paper_closed_trades(namespace TEXT NOT NULL,book TEXT NOT NULL,strategy INTEGER NOT NULL,trade_id TEXT NOT NULL,net_pnl_paise INTEGER NOT NULL,closed_at TEXT NOT NULL,PRIMARY KEY(namespace,book,trade_id));
CREATE TABLE IF NOT EXISTS paper_pause_state(namespace TEXT NOT NULL,scope TEXT NOT NULL,strategy INTEGER NOT NULL,paused INTEGER NOT NULL,cause TEXT,peak_paise INTEGER,pre_pause_peak_paise INTEGER,baseline_day TEXT,paused_at TEXT,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,scope,strategy));
CREATE TABLE IF NOT EXISTS paper_pause_overrides(namespace TEXT NOT NULL,scope TEXT NOT NULL,strategy INTEGER NOT NULL,action TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,scope,strategy,recorded_at));
CREATE TABLE IF NOT EXISTS support_findings(namespace TEXT NOT NULL,finding_id TEXT NOT NULL,status_seq INTEGER NOT NULL,detector TEXT NOT NULL,correlation_id TEXT NOT NULL,first_event_at TEXT NOT NULL,session_day TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('INFO','WARN','ERROR','CRITICAL')),status TEXT NOT NULL CHECK(status IN('OPEN','ACKNOWLEDGED','RESOLVED','WONT_FIX')),observation_only INTEGER NOT NULL DEFAULT 1,notified INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,finding_id,status_seq));
CREATE INDEX IF NOT EXISTS support_findings_session_idx ON support_findings(namespace,session_day,finding_id,status_seq);
CREATE TABLE IF NOT EXISTS support_checkpoints(namespace TEXT PRIMARY KEY,last_recorded_at TEXT NOT NULL,last_event_id TEXT NOT NULL,last_decision_seq INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS daily_prefilter_universe(namespace TEXT NOT NULL,trade_date TEXT NOT NULL,symbol TEXT NOT NULL,policy_version TEXT NOT NULL,status TEXT NOT NULL,eligible INTEGER NOT NULL,pit_series TEXT,metrics_json TEXT NOT NULL,data_hash TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,trade_date,symbol,policy_version));
CREATE INDEX IF NOT EXISTS daily_prefilter_universe_date_idx ON daily_prefilter_universe(namespace,trade_date,eligible,symbol);
CREATE TABLE IF NOT EXISTS bhavcopy_series_archive(trade_date TEXT NOT NULL,symbol TEXT NOT NULL,series TEXT NOT NULL,open REAL,high REAL,low REAL,close REAL,volume INTEGER,turnover REAL,isin TEXT,source TEXT NOT NULL,data_hash TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(trade_date,symbol));
CREATE INDEX IF NOT EXISTS bhavcopy_series_date_idx ON bhavcopy_series_archive(trade_date,series,symbol);
CREATE TABLE IF NOT EXISTS adaptive_tracks(namespace TEXT NOT NULL,track TEXT NOT NULL CHECK(track IN('A','B','C')),strategy INTEGER NOT NULL,slot_index INTEGER NOT NULL DEFAULT 1,spawn_id TEXT NOT NULL,status TEXT NOT NULL,params_json TEXT NOT NULL,allocated_capital_paise INTEGER NOT NULL,cash_paise INTEGER NOT NULL,starting_equity_net_haircut_paise INTEGER NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,track,strategy,slot_index));
CREATE TABLE IF NOT EXISTS adaptive_spawns(namespace TEXT NOT NULL,spawn_id TEXT NOT NULL,correlation_id TEXT NOT NULL,strategy INTEGER NOT NULL,track TEXT NOT NULL CHECK(track IN('A','B','C')),tier TEXT NOT NULL CHECK(tier IN('FAST_SWING','TREND')),parent_version TEXT NOT NULL,params_json TEXT NOT NULL,candidate_kind TEXT NOT NULL CHECK(candidate_kind IN('BASELINE','CANDIDATE','PLACEBO','PLATEAU_NEIGHBOR','SHADOW','TRACK_C_COMPARISON')),eligible_for_selection INTEGER NOT NULL CHECK(eligible_for_selection IN(0,1)),k_cand INTEGER NOT NULL DEFAULT 1,rho_bar REAL NOT NULL DEFAULT 0.0,k_eff REAL NOT NULL DEFAULT 1.0,effective_critical_value REAL NOT NULL DEFAULT 1.40,warm_start_days INTEGER NOT NULL,warm_start_start_date TEXT,warm_start_end_date TEXT,eval_window_target_days INTEGER NOT NULL,eval_window_start_date TEXT,eval_window_end_date TEXT,extension_days INTEGER NOT NULL DEFAULT 0,extension_reason TEXT,starting_equity_gross_paise INTEGER NOT NULL,exit_haircut_paise INTEGER NOT NULL,starting_equity_net_haircut_paise INTEGER NOT NULL,inherited_positions_count INTEGER NOT NULL DEFAULT 0,inherited_discordant_trades INTEGER NOT NULL DEFAULT 0,new_discordant_trades INTEGER NOT NULL DEFAULT 0,distinct_entry_weeks INTEGER NOT NULL DEFAULT 0,harness_hash TEXT NOT NULL,data_snapshot_hash TEXT NOT NULL,rng_seeds_json TEXT NOT NULL,decision_inputs_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('SPAWNED','WARM_START','EVALUATING','EXTENDED','INCONCLUSIVE','PASSED','FAILED','PROMOTED','OBSERVATION_ONLY','PROBATION','RETIRED')),spawned_at TEXT NOT NULL,decided_at TEXT,PRIMARY KEY(namespace,spawn_id));
CREATE INDEX IF NOT EXISTS adaptive_spawns_strategy_idx ON adaptive_spawns(namespace,strategy,track,status);
CREATE TABLE IF NOT EXISTS adaptive_daily_returns(namespace TEXT NOT NULL,spawn_id TEXT NOT NULL,strategy INTEGER NOT NULL,trade_date TEXT NOT NULL,r_var REAL NOT NULL,r_base REAL NOT NULL,d_t REAL NOT NULL,r_index REAL NOT NULL DEFAULT 0.0,equity_var_paise INTEGER NOT NULL,equity_base_paise INTEGER NOT NULL,cash_var_paise INTEGER NOT NULL,cash_base_paise INTEGER NOT NULL,open_positions_var INTEGER NOT NULL DEFAULT 0,open_positions_base INTEGER NOT NULL DEFAULT 0,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,spawn_id,trade_date));
CREATE TABLE IF NOT EXISTS adaptive_gate_evaluations(namespace TEXT NOT NULL,eval_id TEXT NOT NULL,spawn_id TEXT NOT NULL,correlation_id TEXT NOT NULL,strategy INTEGER NOT NULL,decision_day TEXT NOT NULL,k_cand INTEGER NOT NULL,rho_bar REAL NOT NULL,k_eff REAL NOT NULL,effective_critical_value REAL NOT NULL,t_hac REAL NOT NULL,d_t_mean REAL NOT NULL,residual_alpha REAL NOT NULL,residual_beta REAL NOT NULL,beta_stable INTEGER NOT NULL DEFAULT 0,gate4_binding INTEGER NOT NULL DEFAULT 0,gates_json TEXT NOT NULL,overall_passed INTEGER NOT NULL CHECK(overall_passed IN(0,1)),status TEXT NOT NULL,observation_only INTEGER NOT NULL DEFAULT 1,data_hash TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,eval_id));
CREATE TABLE IF NOT EXISTS adaptive_calibration_runs(namespace TEXT NOT NULL,calibration_id TEXT NOT NULL,correlation_id TEXT NOT NULL,strategy INTEGER NOT NULL,partition_name TEXT NOT NULL,sigma_d_t REAL NOT NULL,mde REAL NOT NULL,injected_edge REAL NOT NULL,measured_power REAL NOT NULL,power_floor REAL NOT NULL,go_no_go TEXT NOT NULL CHECK(go_no_go IN('GO','NO_GO_MONITOR_ONLY','NO_GO_LENGTHEN_WINDOW')),pipeline_mode TEXT NOT NULL,holdout_touched INTEGER NOT NULL DEFAULT 0,vault_spent INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL,data_hash TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(namespace,calibration_id));
CREATE TABLE IF NOT EXISTS adaptive_holdout_vault(namespace TEXT NOT NULL,vault_id TEXT NOT NULL,touched_count INTEGER NOT NULL DEFAULT 0,vault_spent INTEGER NOT NULL DEFAULT 0,first_touched_at TEXT,calibration_id TEXT,status TEXT NOT NULL,details_json TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,vault_id));
CREATE TABLE IF NOT EXISTS adaptive_probation(namespace TEXT NOT NULL,probation_id TEXT NOT NULL,spawn_id TEXT NOT NULL,strategy INTEGER NOT NULL,tolerance_band_sigma REAL NOT NULL,historical_tracking_error REAL NOT NULL,tracking_error_limit REAL NOT NULL,days_monitored INTEGER NOT NULL DEFAULT 0,required_days INTEGER NOT NULL,cumulative_active_return REAL NOT NULL DEFAULT 0.0,status TEXT NOT NULL,meta_kill_triggered INTEGER NOT NULL DEFAULT 0,details_json TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(namespace,probation_id));
CREATE TABLE IF NOT EXISTS adaptive_decision_logs(namespace TEXT NOT NULL,seq INTEGER NOT NULL,log_id TEXT NOT NULL,correlation_id TEXT NOT NULL,spawn_id TEXT,order_id TEXT,track TEXT NOT NULL CHECK(track IN('A','B','C','SYSTEM')),strategy INTEGER,symbol TEXT,category TEXT NOT NULL,decision_type TEXT NOT NULL,named_cause TEXT,rule_fired TEXT,execution_path TEXT,strategy_version TEXT,conditions_json TEXT NOT NULL,filters_json TEXT NOT NULL,indicator_snapshot_json TEXT NOT NULL,risk_state_json TEXT NOT NULL,execution_details_json TEXT NOT NULL,data_hash TEXT NOT NULL,source_at TEXT NOT NULL,recorded_at TEXT NOT NULL,prev_hash TEXT NOT NULL,entry_hash TEXT NOT NULL,PRIMARY KEY(namespace,seq));
CREATE INDEX IF NOT EXISTS adaptive_logs_corr_idx ON adaptive_decision_logs(namespace,correlation_id,seq);
CREATE INDEX IF NOT EXISTS adaptive_logs_spawn_idx ON adaptive_decision_logs(namespace,spawn_id,seq);
CREATE INDEX IF NOT EXISTS adaptive_logs_query_idx ON adaptive_decision_logs(namespace,track,strategy,symbol,category,named_cause);
